suspend fun ask(p: QuoteProvider, pair: String): Quote? =
    try {
        withTimeoutOrNull(300.milliseconds) {               // null when time is up
            runInterruptible(Dispatchers.IO) {              // interrupts the thread on cancel
                Quote(p.name(), p.quote(pair))
            }
        }
    } catch (e: CancellationException) {
        throw e                                             // never swallow cancellation
    } catch (e: Exception) {
        null                                                // a failure becomes "no answer"
    }

